BEGIN;
CREATE TABLE IF NOT EXISTS applications (id BIGSERIAL PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS controlm_environments (id BIGSERIAL PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE, api_base_url VARCHAR(500) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS application_ad_groups (id BIGSERIAL PRIMARY KEY, application_id BIGINT NOT NULL REFERENCES applications(id), ad_group_name VARCHAR(255) NOT NULL, role VARCHAR(40) NOT NULL CHECK (role IN ('VIEWER','OPERATOR','APP_ADMIN')), is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(application_id, ad_group_name, role));
CREATE TABLE IF NOT EXISTS plan_refresh_runs (id BIGSERIAL PRIMARY KEY, environment_id BIGINT NOT NULL REFERENCES controlm_environments(id), plan_date DATE, started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), finished_at TIMESTAMPTZ, status VARCHAR(30) NOT NULL DEFAULT 'RUNNING', records_seen INTEGER NOT NULL DEFAULT 0, error_summary TEXT);
CREATE TABLE IF NOT EXISTS folders (id BIGSERIAL PRIMARY KEY, environment_id BIGINT NOT NULL REFERENCES controlm_environments(id), application_id BIGINT NOT NULL REFERENCES applications(id), controlm_server VARCHAR(255) NOT NULL, folder_name VARCHAR(255) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(environment_id, controlm_server, folder_name));
CREATE TABLE IF NOT EXISTS job_instances (id BIGSERIAL PRIMARY KEY, refresh_run_id BIGINT REFERENCES plan_refresh_runs(id), folder_id BIGINT NOT NULL REFERENCES folders(id), controlm_server VARCHAR(255) NOT NULL, folder_name VARCHAR(255) NOT NULL, job_name VARCHAR(255) NOT NULL, order_id VARCHAR(255) NOT NULL, order_date DATE, api_job_id VARCHAR(600) NOT NULL, observed_status VARCHAR(100), snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), is_current BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX IF NOT EXISTS ix_job_instances_folder_current ON job_instances(folder_id, is_current);
CREATE INDEX IF NOT EXISTS ix_job_instances_name ON job_instances(job_name);
CREATE INDEX IF NOT EXISTS ix_job_instances_api_job_id ON job_instances(api_job_id);
CREATE TABLE IF NOT EXISTS automation_requests (id BIGSERIAL PRIMARY KEY, request_number VARCHAR(40) NOT NULL UNIQUE, requested_by VARCHAR(255) NOT NULL, application_id BIGINT NOT NULL REFERENCES applications(id), environment_id BIGINT NOT NULL REFERENCES controlm_environments(id), job_instance_id BIGINT NOT NULL REFERENCES job_instances(id), action_type VARCHAR(20) NOT NULL CHECK (action_type IN ('HOLD','RELEASE')), status VARCHAR(30) NOT NULL DEFAULT 'SUBMITTED', controlm_http_status INTEGER, result_summary TEXT, correlation_id VARCHAR(64) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS request_events (id BIGSERIAL PRIMARY KEY, request_id BIGINT NOT NULL REFERENCES automation_requests(id), event_type VARCHAR(40) NOT NULL, actor VARCHAR(255) NOT NULL, message TEXT, event_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ix_automation_requests_created ON automation_requests(created_at DESC);
CREATE INDEX IF NOT EXISTS ix_request_events_request ON request_events(request_id, event_at);
COMMIT;
